  M['bx1-u3-l8'] =   {
    "title": "声声慢",
    "src": "李清照《声声慢》",
    "segments": [
      {
        "text": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他、晚来风急！雁过也，正伤心，却是旧时相识。",
        "note": "开篇七组叠字\"寻寻觅觅……戚戚\"层层递转，写孤寂凄凉的心境，创千古绝调；\"淡酒\"\"晚风\"\"过雁\"以秋景衬愁，雁乃\"旧时相识\"更添物是人非之痛。"
      },
      {
        "text": "满地黄花堆积，憔悴损，如今有谁堪摘？守着窗儿，独自怎生得黑！梧桐更兼细雨，到黄昏、点点滴滴。这次第，怎一个愁字了得！",
        "note": "下阕由黄花憔悴写到梧桐细雨，\"点点滴滴\"延宕至黄昏；结句\"怎一个愁字了得\"以反诘收束，将亡国之悲、孀居之愁推向极致，余味无穷。"
      }
    ],
    "full": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他、晚来风急！雁过也，正伤心，却是旧时相识。\n\n满地黄花堆积，憔悴损，如今有谁堪摘？守着窗儿，独自怎生得黑！梧桐更兼细雨，到黄昏、点点滴滴。这次第，怎一个愁字了得！"
  };
