  M['xb1-u1-l1'] =   {
    "title": "中国人民站起来了",
    "src": "毛泽东《中国人民站起来了》",
    "segments": [
      {
        "text": "诸位代表先生们，全国人民所渴望的政治协商会议现在开幕了。\n我们的会议包括六百多位代表，代表着全中国所有的民主党派，人民团体，人民解放军，各地区，各民族和国外华侨。这就指明，我们的会议是一个全国人民大团结的会议。",
        "note": "开幕词起笔即点明会议的性质——\"全国人民大团结的会议\"，以\"渴望\"\"六百多位代表\"写新政权包容性与合法性，庄重而充满历史感。"
      },
      {
        "text": "我们的民族将从此列入爱好和平自由的世界各民族的大家庭，以勇敢而勤劳的姿态工作着，创造自己的文明和幸福，在自由的天空下，站立起来，一个真正站立起来的民族。\n让那些内外反动派在我们面前发抖罢，让他们去说我们这也不行那也不行罢，中国人民的不屈不挠的努力必将稳步地达到自己的目的。",
        "note": "\"站立起来\"是全文题眼，宣告民族独立与人民解放；结句以\"让那些内外反动派发抖罢\"的豪情，彰显站起来的中国人民不可动摇的自信。"
      }
    ],
    "full": "诸位代表先生们，全国人民所渴望的政治协商会议现在开幕了。\n我们的会议包括六百多位代表，代表着全中国所有的民主党派，人民团体，人民解放军，各地区，各民族和国外华侨。这就指明，我们的会议是一个全国人民大团结的会议。\n\n我们的民族将从此列入爱好和平自由的世界各民族的大家庭，以勇敢而勤劳的姿态工作着，创造自己的文明和幸福，在自由的天空下，站立起来，一个真正站立起来的民族。\n让那些内外反动派在我们面前发抖罢，让他们去说我们这也不行那也不行罢，中国人民的不屈不挠的努力必将稳步地达到自己的目的。"
  };
