    "title": "大学之道",
    "src": "《礼记·大学》",
    "segments": [
      {
        "text": "大学之道，在明明德，在亲民，在止于至善。知止而后有定，定而后能静，静而后能安，安而后能虑，虑而后能得。物有本末，事有终始。知所先后，则近道矣。",
        "note": "开篇揭\"三纲领\"：明明德、亲民、止于至善；\"知止—定—静—安—虑—得\"示为学次第，由本末终始入手，近道之方豁然。"
      },
      {
        "text": "古之欲明明德于天下者，先治其国。欲治其国者，先齐其家。欲齐其家者，先修其身。欲修其身者，先正其心。欲正其心者，先诚其意。欲诚其意者，先致其知。致知在格物。",
        "note": "展开\"八条目\"：格物、致知、诚意、正心、修身、齐家、治国、平天下，由内而外、由近及远，构成儒家内圣外王的修养链。"
      },
      {
        "text": "物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。自天子以至于庶人，壹是皆以修身为本。",
        "note": "回环递进展现八条目之因果，\"壹是皆以修身为本\"收束，强调人人皆须以修身为根，平实中见宏大格局。"
      }
    ],
    "full": "大学之道，在明明德，在亲民，在止于至善。知止而后有定，定而后能静，静而后能安，安而后能虑，虑而后能得。物有本末，事有终始。知所先后，则近道矣。\n\n古之欲明明德于天下者，先治其国。欲治其国者，先齐其家。欲齐其家者，先修其身。欲修其身者，先正其心。欲正其心者，先诚其意。欲诚其意者，先致其知。致知在格物。\n\n物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。自天子以至于庶人，壹是皆以修身为本。"
