    "full": "岂曰无衣？与子同袍。王于兴师，修我戈矛，与子同仇！\n岂曰无衣？与子同泽。王于兴师，修我矛戟，与子偕作！\n岂曰无衣？与子同裳。王于兴师，修我甲兵，与子偕行！"
