  M['xb2-u1-l6'] =   {
    "title": "怜悯是人的天性",
    "src": "卢梭《怜悯是人的天性》",
    "segments": [
      {
        "text": "在远古时期，人……在自然状态中，怜悯心先于一切思考而存在；它是天然的，先于理性而存在。当目睹一个动物陷于痛苦时，即使是最凶狠的人也会心生恻隐。",
        "note": "（节选）卢梭在《论人类不平等的起源和基础》中主张：怜悯（同情）乃自然人先于理性的天然情感，是道德的发端，以此批判霍布斯的\"人性本恶说\"。"
      },
      {
        "text": "正是这种怜悯心，在自然状态中代替了法律、风俗和道德，使人类得以自我保存而不相侵害；它缓减了每个人自保的强烈欲念，促成了族类间的互助。",
        "note": "进一步说明怜悯心\"代替法律道德\"维系自然秩序，是契约社会之前的人性纽带，体现卢梭对自然状态的理想化想象。"
      }
    ],
    "full": "在远古时期，人……在自然状态中，怜悯心先于一切思考而存在；它是天然的，先于理性而存在。当目睹一个动物陷于痛苦时，即使是最凶狠的人也会心生恻隐。\n\n正是这种怜悯心，在自然状态中代替了法律、风俗和道德，使人类得以自我保存而不相侵害；它缓减了每个人自保的强烈欲念，促成了族类间的互助。"
  };
  M['xb2-u1-l7'] =   {
    "title": "人应当坚持正义",
    "src": "柏拉图《人应当坚持正义》",
    "segments": [
      {
        "text": "（苏格拉底面对不义的判决）\"公民们！我尊敬、热爱你们；但是我将服从神，而不是你们。只要我还有一口气，我就绝不停下哲学的实践。\"",
        "note": "（节选·苏格拉底的申辩）宁违众意而服从真理与神谕，彰显\"服从道义高于服从多数人\"的哲人立场。"
      },
      {
        "text": "（克力同劝其逃亡）\"我们应当追问：在何种情形下，背离法律才是正当的？若法律使我们受益、我们却在其判决不利时便背弃它，岂非以私利毁弃契约？\"",
        "note": "借《克力同》对话表明：法律如城邦与公民之契约，不可因一时利害而毁；\"守法即守正义\"收束。"
      }
    ],
    "full": "（苏格拉底面对不义的判决）\"公民们！我尊敬、热爱你们；但是我将服从神，而不是你们。只要我还有一口气，我就绝不停下哲学的实践。\"\n\n（克力同劝其逃亡）\"我们应当追问：在何种情形下，背离法律才是正当的？若法律使我们受益、我们却在其判决不利时便背弃它，岂非以私利毁弃契约？\""
  };
  M['xb2-u2-l1'] =   {
    "title": "记念刘和珍君",
    "src": "鲁迅《记念刘和珍君》",
    "segments": [
      {
        "text": "中华民国十五年三月二十五日，就是国立北京女子师范大学为十八日在段祺瑞执政府前遇害的刘和珍杨德群两君开追悼会的那一天，我独在礼堂外徘徊……",
        "note": "开篇以追悼会日期落笔，沉痛纪时；\"独在礼堂外徘徊\"写悲不能己，定下哀婉而愤激的基调。"
      },
      {
        "text": "真的猛士，敢于直面惨淡的人生，敢于正视淋漓的鲜血。这是怎样的哀痛者和幸福者？……苟活者在淡红的血色中，会依稀看见微茫的希望；真的猛士，将更奋然而前行。",
        "note": "\"真的猛士\"一节为全文警策：以\"哀痛者\"与\"幸福者\"的悖论礼赞勇者；\"淡红的血色\"中见希望，悲愤里含激励。"
      },
      {
        "text": "我没有亲见；听说，她，刘和珍君，那时是欣然前往的。……始终微笑的和蔼的刘和珍君确是死掉了，这是真的，有她自己的尸骸为证！",
        "note": "以\"始终微笑的和蔼的\"反衬惨死之酷，\"尸骸为证\"四字如铁，控诉执政府虐杀青年的罪行，柔情与愤火交织。"
      },
      {
        "text": "惨象，已使我目不忍视了；流言，尤使我耳不忍闻。我还有什么话可说呢？我懂得衰亡民族之所以默无声息的缘由了。沉默呵，沉默呵！不在沉默中爆发，就在沉默中灭亡。",
        "note": "结以\"沉默中爆发或灭亡\"的千古名句，将一己悲愤升华为对民族存亡的终极诘问，沉郁顿挫，力重千钧。"
      }
    ],
    "full": "中华民国十五年三月二十五日，就是国立北京女子师范大学为十八日在段祺瑞执政府前遇害的刘和珍杨德群两君开追悼会的那一天，我独在礼堂外徘徊……\n\n真的猛士，敢于直面惨淡的人生，敢于正视淋漓的鲜血。这是怎样的哀痛者和幸福者？……苟活者在淡红的血色中，会依稀看见微茫的希望；真的猛士，将更奋然而前行。\n\n我没有亲见；听说，她，刘和珍君，那时是欣然前往的。……始终微笑的和蔼的刘和珍君确是死掉了，这是真的，有她自己的尸骸为证！\n\n惨象，已使我目不忍视了；流言，尤使我耳不忍闻。我还有什么话可说呢？我懂得衰亡民族之所以默无声息的缘由了。沉默呵，沉默呵！不在沉默中爆发，就在沉默中灭亡。"
  };
  M['xb2-u2-l2'] =   {
    "title": "为了忘却的记念",
    "src": "鲁迅《为了忘却的记念》",
    "segments": [
      {
        "text": "我早已想写一点文字来记念几个青年的作家，这并非为了别的，只因为两年以来，悲愤总时时来袭击我的心，至今没有停止……\n夜正长，路也正长，我不如忘却，不说的好罢。但我知道，即使不是我，将来总会有记起他们，再说他们的时候的。",
        "note": "题为\"为了忘却\"，实则以记念对抗遗忘；\"夜正长，路也正长\"喻黑暗与抗争之持久，\"总会有记起他们的时候\"于绝望中燃希望。"
      },
      {
        "text": "（忆柔石）\"只要教育，我以为。\"\"他会去接谈，也会去译书。\"……我有时谈到人会怎样的骗人，怎样的卖友，怎样的吮血，他就前额亮晶晶地，惊疑地圆睁了近视的眼睛。",
        "note": "以柔石\"惊疑圆睁的近视眼\"写其天真纯良、不谙世故，与后文惨遭杀害形成刺痛对照。"
      },
      {
        "text": "（引诗）惯于长夜过春时，挈妇将雏鬓有丝。梦里依稀慈母泪，城头变幻大王旗。忍看朋辈成新鬼，怒向刀丛觅小诗。吟罢低眉无写处，月光如水照缁衣。",
        "note": "嵌《无题》七律，\"忍看朋辈成新鬼，怒向刀丛觅小诗\"以诗记恨，于月冷水寒中见不屈。"
      },
      {
        "text": "不是年青的为年老的所忘却，先驱者的血，而倘不恤其错误，便是懦怯。\n（结）不是年青的为年老的所忘却，先驱者的血，而倘不恤其错误，便是懦怯。夜正长，路也正长，我不如忘却，不说的好罢。但我知道，即使不是我，将来总会有记起他们，再说他们的时候的。",
        "note": "结语以\"夜正长，路也正长\"收束，将个人悲愤升华为对民族前途的坚定信念，余韵苍凉而有力。"
      }
    ],
    "full": "我早已想写一点文字来记念几个青年的作家，这并非为了别的，只因为两年以来，悲愤总时时来袭击我的心，至今没有停止……\n夜正长，路也正长，我不如忘却，不说的好罢。但我知道，即使不是我，将来总会有记起他们，再说他们的时候的。\n\n（忆柔石）\"只要教育，我以为。\"\"他会去接谈，也会去译书。\"……我有时谈到人会怎样的骗人，怎样的卖友，怎样的吮血，他就前额亮晶晶地，惊疑地圆睁了近视的眼睛。\n\n（引诗）惯于长夜过春时，挈妇将雏鬓有丝。梦里依稀慈母泪，城头变幻大王旗。忍看朋辈成新鬼，怒向刀丛觅小诗。吟罢低眉无写处，月光如水照缁衣。\n\n不是年青的为年老的所忘却，先驱者的血，而倘不恤其错误，便是懦怯。\n（结）不是年青的为年老的所忘却，先驱者的血，而倘不恤其错误，便是懦怯。夜正长，路也正长，我不如忘却，不说的好罢。但我知道，即使不是我，将来总会有记起他们，再说他们的时候的。"
  };
  M['xb2-u2-l3'] =   {
    "title": "包身工",
    "src": "夏衍《包身工》",
    "segments": [
      {
        "text": "已经是旧历四月中旬了，上午四点一刻，晓星才从慢慢地推移着的淡云里消去，蜂房般的格子铺里的生物已在蠕动了。",
        "note": "（节选）以\"蜂房般的格子铺\"\"生物\"喻包身工如虫豸般被囚，清晨四点即起的反常，揭开盘剥制度的残酷，纪实笔法冷峻如刀。"
      },
      {
        "text": "\"芦柴棒\"着急地要将大锅里的稀饭烧滚，但是倒冒出来的青烟引起了她一阵猛烈的咳嗽。",
        "note": "以\"芦柴棒\"这一典型包身工的咳嗽特写，写其羸弱与劳碌，\"冒青烟\"的细节刺目，是报告文学\"用事实说话\"的力证。"
      }
    ],
    "full": "已经是旧历四月中旬了，上午四点一刻，晓星才从慢慢地推移着的淡云里消去，蜂房般的格子铺里的生物已在蠕动了。\n\n\"芦柴棒\"着急地要将大锅里的稀饭烧滚，但是倒冒出来的青烟引起了她一阵猛烈的咳嗽。",
    "copyright": true
  };
