    "full": "再见吧，自由奔放的大海！\n这是你最后一次在我的眼前，\n翻滚着蔚蓝色的波浪，\n和闪耀着娇美的容光。\n好像是朋友忧郁的怨诉，\n好像是他在临别时的呼唤——\n我最后一次在倾听\n你悲哀的喧响，你召唤的喧响。\n\n你是我心灵的愿望之所在呀！\n我时常沿着你的岸旁，\n一个人静悄悄地，茫然地徘徊，\n还因为那个隐秘的梦想\n每每无心肠地让你悲伤……"
