    "full": "一棵树在雨中行走。\n在倾洒的灰色中匆匆走过\n我们身旁。它有急事。\n它从雨中汲取生命\n犹如果园里黑色的山雀。\n\n雨歇了。树停住脚步。\n它长在ric间。它张开新发的叶子\n触摸软管般的春雨\n我们正经历着变故。我们正经历着\n升起和落下。",
