    "full": "由四川过湖南去，靠东有一条官路。这官路将近湘西边境到了一个地方名为\"茶峒\"的小山城时，有一小溪，溪边有座白色小塔，塔下住了一户单独的人家。\n\n这人家只一个老人，一个女孩子，一只黄狗。",
