    "full": "（第一幕·戊戌变法失败后）裕泰茶馆里，三三两两的茶客议论时局。常四爷叹道：\"我看哪，大清国要完！\"便被侦缉队宋恩子、吴祥子以\"谭嗣同余党\"之名拿办。\n\n（尾声·解放前）当年的人物大多凋零，茶馆易主，王利发、秦仲义、常四爷三位老人撒纸钱自祭，笑语凄凉：\"改良！改良！越改越凉，冰凉！\""
